properties.query:
let baselineWindow = 1d;
let recentWindow = 15m;
let parser = NextDNS_Parser()
| where EventSchema =~ 'Dns'
| where EventResult =~ 'Failure'
| extend ProfileId = tostring(AdditionalFields.ProfileId), Reasons = tostring(AdditionalFields.Reasons);
let baseline = parser
| where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
| summarize baselineBlocked = count() by ProfileId, SrcIpAddr;
let recent = parser
| where TimeGenerated >= ago(recentWindow)
| summarize recentBlocked = count(), SampleDomains = make_set(DnsQuery, 5), SampleReasons = make_set(Reasons, 3) by ProfileId, SrcIpAddr, Dvc;
recent
| join kind=leftouter baseline on ProfileId, SrcIpAddr
| extend baselineBlocked = coalesce(baselineBlocked, 0)
| where recentBlocked >= 100 and recentBlocked > baselineBlocked * 3
| project TimeGenerated = now(), ProfileId, SrcIpAddr, Dvc, recentBlocked, baselineBlocked, SampleDomains, SampleReasons

let baseline = NextDNS_Parser()
| where TimeGenerated between (ago(14d) .. ago(1h))
| where EventSchema =~ 'Dns'
| summarize by DnsQueryDomain;
let recent = NextDNS_Parser()
| where TimeGenerated >= ago(1h)
| where EventSchema =~ 'Dns'
| summarize QueryCount = count(), SrcIps = dcount(SrcIpAddr), Devices = dcount(Dvc), SampleQueries = make_set(DnsQuery, 10) by DnsQueryDomain, ProfileId = tostring(AdditionalFields.ProfileId);
recent
| join kind=leftanti baseline on DnsQueryDomain
| where QueryCount >= 25 and SrcIps >= 3
| project TimeGenerated = now(), ProfileId, DnsQueryDomain, QueryCount, SrcIps, Devices, SampleQueries

let recentWindow = 2h;
let statusData = NextDNSAnalytics_Parser()
| where TimeGenerated >= ago(recentWindow)
| where metric == 'status'
| project TimeGenerated, profileId, itemName = tolower(itemName), queryCount;
let blocked = statusData
| where itemName == 'blocked'
| summarize blockedQueries = sum(queryCount) by profileId;
let total = statusData
| summarize totalQueries = sum(queryCount) by profileId;
blocked
| join kind=inner total on profileId
| extend blockedRatio = iff(totalQueries == 0, 0.0, todouble(blockedQueries) / todouble(totalQueries))
| where blockedQueries >= 500 and blockedRatio >= 0.4
| project TimeGenerated = now(), profileId, blockedQueries, totalQueries, blockedRatio
